  function automatic logic [127:0]
      prim_secded_128_120_enc (logic [119:0] data_i);
    logic [127:0] data_o;
    data_o = 128'(data_i);
    data_o[120] = ^(data_o & 128'h007F000007FFFFFFFF000000001FFFFF);
    data_o[121] = ^(data_o & 128'h00BF03FFF8000FFFFF00000FFFE0003F);
    data_o[122] = ^(data_o & 128'h00DF7C1FF83FF003FF003FF003E007C1);
